+23|    if (abs >= 1e12) return (v / 1e12).toFixed(2) + "T";
+24|    if (abs >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
+25|    if (abs >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
+26|    if (abs >= 1e3)  return (v / 1e3).toFixed(2)  + "K";
+27|    return String(v);
