+59|
+60|    data.forEach(d => {
+61|        d.radius = d.isETF ? ETF_RADIUS : rScale(d.marketCap);
+62|    });
+63|
+64|    // Cluster centers: arrange 5 sectors in a tight pentagon-like layout around the plot center.
+65|    const cx = PLOT_W / 2;
+66|    const cy = PLOT_H / 2;
