+147|    // Stop after convergence for a stable layout.
+148|    simulation.alpha(1).restart();
+149|    for (let i = 0; i < 300; i++) simulation.tick();
+150|    node.attr("transform", d => `translate(${d.x},${d.y})`);
+151|    simulation.alphaTarget(0).stop();
+152|
+153|    // Legend
+154|    const legend = svg.append("g")
+155|        .attr("class", "legend")
+156|        .attr("transform", `translate(${WIDTH - MARGIN.right + 20},${MARGIN.top + 10})`);
+157|
+158|    legend.append("text")
+159|        .attr("x", 0).attr("y", 0)
+160|        .style("font-weight", 600)
+161|        .style("font-size", "13px")
+162|        .text("Sector");
+163|
+164|    const legendRows = legend.selectAll("g.legend-row")
+165|        .data(SECTORS)
+166|        .join("g")
+167|        .attr("class", "legend-row")
+168|        .attr("transform", (_, i) => `translate(0, ${20 + i * 22})`);
+169|
+170|    legendRows.append("circle")
+171|        .attr("cx", 8).attr("cy", 0)
+172|        .attr("r", 7)
+173|        .attr("fill", s => COLORS[s]);
+174|
+175|    legendRows.append("text")
+176|        .attr("x", 22).attr("y", 4)
+177|        .text(s => s);
+178|
+179|    // Expose selector so the table can use it.
+180|    window.__selectBubble = function (ticker) {
+181|        plot.selectAll("circle.bubble")
+182|            .classed("selected", d => d.ticker === ticker);
+183|    };
+184|}
+185|
+186|function renderTable(data) {
+187|    const tbody = d3.select("#stock-table tbody");
+188|
+189|    const rows = tbody.selectAll("tr")
+190|        .data(data, d => d.ticker)
+191|        .join("tr")
+192|        .attr("data-ticker", d => d.ticker);
+193|
+194|    rows.append("td").text(d => d.ticker);
+195|    rows.append("td").text(d => d.name);
+196|    rows.append("td").html(d =>
+197|        `<span class="sector-chip" style="background:${COLORS[d.sector]}"></span>${escapeHTML(d.sector)}`
+198|    );
+199|    rows.append("td").text(d => formatMarketCap(d.marketCap));
+200|
+201|    rows.on("click", function (event, d) {
+202|        selectTicker(d.ticker);
+203|    });
+204|
+205|    window.__selectRow = function (ticker) {
+206|        tbody.selectAll("tr").classed("selected", d => d.ticker === ticker);
+207|        const el = tbody.select(`tr[data-ticker="${ticker}"]`).node();
+208|        if (el && el.scrollIntoView) {
+209|            el.scrollIntoView({ block: "nearest", behavior: "smooth" });
+210|        }
+211|    };
+212|}
+213|
+214|function selectTicker(ticker) {
+215|    if (window.__selectBubble) window.__selectBubble(ticker);
